import json, sys

J = 'job="day25-work-view"'
R = '[$__range]'
P = {"type": "prometheus", "uid": "prometheus"}
L = {"type": "loki", "uid": "loki"}
GRAY = "#808080"


def st(extra=""):
    return 'max by (run)(last_over_time(work_status{%s%s}%s))' % (J, extra, R)


def stfull(s):
    return 'max by (run, scenario, status, reason)(last_over_time(work_status{%s,status="%s"}%s))' % (J, s, R)


def stage(n):
    return 'max by (run)(last_over_time(work_stage_count{%s,stage_order="%d"}%s))' % (J, n, R)


def pq(ref, expr):
    return {"refId": ref, "datasource": P, "instant": True, "range": False, "format": "table", "expr": expr}


order = ('label_join((%s*0+1) or (%s*0+2) or (%s*0+3), "note", "-", "status", "reason")'
         % (stfull("investigate"), stfull("unknown"), stfull("matched")))
NU = st(',status!="unknown"')
UNK = st(',status="unknown"')
stuck = ('(((((%s < %s)*0+2) or ((%s < %s)*0+3) or ((%s < %s)*0+4)) and on(run) %s) or (%s*0+99) or (%s*0))'
         % (stage(2), stage(1), stage(3), stage(2), stage(4), stage(3), NU, UNK, NU))

TIMES = {("Time" + s): True for s in ["", " 1", " 2", " 3", " 4", " 5", " 6", " 7"]}


def join_sort():
    return [{"id": "joinByField", "options": {"byField": "run", "mode": "outer"}},
            {"id": "sortBy", "options": {"fields": {}, "sort": [{"field": "Value #A"}]}}]


def vmap(d):
    return {"type": "value", "options": {k: {"text": t, "color": c, "index": i} for i, (k, (t, c)) in enumerate(d.items())}}


def ov(name, props):
    return {"matcher": {"id": "byName", "options": name}, "properties": props}


def stat(id_, x, title, desc, status, color):
    steps = [{"color": "text", "value": None}]
    if color:
        steps.append({"color": color, "value": 1})
    return {"id": id_, "type": "stat", "title": title, "description": desc, "datasource": P,
            "gridPos": {"h": 4, "w": 8, "x": x, "y": 1},
            "targets": [{"refId": "A", "datasource": P, "instant": True, "range": False, "format": "time_series",
                         "expr": 'count(%s) or vector(0)' % st(',status="%s"' % status)}],
            "fieldConfig": {"defaults": {"unit": "suffix: 輪", "decimals": 0, "noValue": "0 輪",
                                         "thresholds": {"mode": "absolute", "steps": steps}},
                            "overrides": []},
            "options": {"reduceOptions": {"calcs": ["lastNotNull"], "fields": "", "values": False},
                        "colorMode": "value", "graphMode": "none", "textMode": "value",
                        "justifyMode": "center", "orientation": "auto"}}


def row(id_, y, title, collapsed=False, panels=None):
    return {"id": id_, "type": "row", "title": title, "collapsed": collapsed,
            "gridPos": {"h": 1, "w": 24, "x": 0, "y": y}, "panels": panels or []}


t1 = {
    "id": 6, "type": "table", "title": "每一輪的結論（最需要處理的排最前面）",
    "description": "紅色＝需要處理；灰色＝資料不足、還無法判斷（不是失敗，也不是沒問題）；沒有顏色＝已確認沒問題。",
    "datasource": P, "gridPos": {"h": 8, "w": 24, "x": 0, "y": 5},
    "targets": [pq("A", order),
                pq("B", 'max by (run)(last_over_time(work_unmatched{%s}%s)) and on(run) %s' % (J, R, NU))],
    "transformations": join_sort() + [{"id": "organize", "options": {
        "excludeByName": {**TIMES, "run": True, "reason": True, "Value #A": True},
        "indexByName": {"scenario": 0, "status": 1, "Value #B": 2, "note": 3},
        "renameByName": {"scenario": "輪次", "status": "結論", "Value #B": "沒收到確認的筆數", "note": "說明"}}}],
    "fieldConfig": {"defaults": {"custom": {"align": "auto", "cellOptions": {"type": "auto"}}},
        "overrides": [
            ov("結論", [{"id": "custom.cellOptions", "value": {"type": "color-background", "mode": "basic"}},
                        {"id": "mappings", "value": [vmap({"investigate": ("需要處理", "red"), "unknown": ("資料不足", GRAY),
                                                           "matched": ("已確認沒問題", "transparent")})]},
                        {"id": "custom.width", "value": 150}]),
            ov("沒收到確認的筆數", [{"id": "custom.cellOptions", "value": {"type": "color-text"}},
                        {"id": "unit", "value": "suffix: 筆"}, {"id": "decimals", "value": 0},
                        {"id": "thresholds", "value": {"mode": "absolute", "steps": [{"color": "text", "value": None}, {"color": "red", "value": 1}]}},
                        {"id": "mappings", "value": [{"type": "special", "options": {"match": "null+nan", "result": {"text": "還無法判斷", "color": GRAY, "index": 0}}}]},
                        {"id": "custom.width", "value": 170}]),
            ov("說明", [{"id": "mappings", "value": [vmap({
                "matched-identity_reconciliation": ("每一筆都有收到對方確認", "text"),
                "investigate-identity_reconciliation": ("有幾筆對方沒收到確認，請到最下面逐筆查", "text"),
                "unknown-missing_notification_identity": ("大部分通知缺少可核對的編號，現在判斷不出來，要先補資料", GRAY)})]}])]},
    "options": {"showHeader": True, "cellHeight": "sm"}}

t2 = {
    "id": 8, "type": "table", "title": "每一輪走到哪一段、卡在哪一段",
